import * as THREE from 'three/webgpu';
import { texture, uv, add, mul, normalize, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();
  container.position.copy(config.sceneNode?.position || { x: 0, y: 0, z: 0 });
  container.rotation.order = 'YXZ';

  // Load textures
  const colorTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);
  colorTexture.flipY = false;
  depthTexture.flipY = false;

  // Create parallax plane mesh
  const planeGeometry = new THREE.PlaneGeometry(4.0, 2.5, 64, 64);
  const planeMaterial = createFilmicMaterial(colorTexture, depthTexture);
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  container.add(planeMesh);

  // Create caption block (text + accent bar)
  const captionGroup = createCaptionBlock(config, ctx);
  captionGroup.position.set(-1.75, -1.0, 0.01);
  container.add(captionGroup);

  // Setup entrance animations
  setupEntranceAnimations(planeMesh, captionGroup);

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](container, primitive.params);
      }
    });
  }

  // Cleanup resources
  container.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
    gsap.killTweensOf([planeMaterial, captionGroup.position]);
  };

  return container;
}

function createFilmicMaterial(colorTexture, depthTexture) {
  const material = new THREE.NodeMaterial();
  material.transparent = true;

  // TSL nodes
  const uvCoord = uv();
  const colorSample = texture(colorTexture, uvCoord);
  const depthSample = texture(depthTexture, uvCoord);

  // Apply filmic grade: sample color and layer in depth for silhouette definition
  material.colorNode = colorSample;

  // Setup opacity for fade-in animation
  material.opacity = 0;

  // Store depth for parallax interaction (cinematic primitive will reference this)
  material.userData.depthSample = depthSample;
  material.userData.displacementScale = 0.18;

  return material;
}

